DECLARE packs jsonb := $pack$[{"codigo":"S22BA-448-1","legacy_id":448,"relacionadas":["S22C-C02","S22E-C01"],"coberturas":[{"legacy_id":448,"estado_cobertura":"PARCIAL","residual":"Operación OTP_OP_B2B_AUTH_PASSWORD_RECOVERY_EMAIL, política OTP_POL_B2B_AUTH_EMAIL_BREVO, ruta B2B_ROUTE_AUTH_RECOVERY_VERIFY, error LF-B2B-AUTH-006 y política SEC-B2B-AUTH-PROVIDER-ARCHITECTURE existen pero CANDIDATO; falta evidencia de emisión/consumo de grant opaco temporal de uso único y binding runtime. No autoriza producción.","diferencias":"Cubre verificación de recuperación y contexto restringido entre pantallas B2B de origen; fuente CANDIDATO, contratos físicos candidatos y runtime pendiente."}],"paquete":{"tipo":"NUEVA","codigo":"S22BA-448-1","clave":"s22ba_legacy_448_0","familia":"MFA_OTP_SSO","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"B2B_AUTENTICACION","modo":"HEREDA","dueno":"TECNICO","titulo":"OTP de recuperación verificado y contexto restringido B2B","descripcion":"BLOQUEAR verificación B2B-AUTH-006 y acceso a B2B-AUTH-003 si OTP PASSWORD_RECOVERY no es verificado por servidor mediante operación, política, ruta y arquitectura de seguridad gobernadas; solo verificación válida emite contexto opaco temporal de uso único PASSWORD_UPDATE_ONLY. No concede acceso operativo, no satisface MFA, cliente no puede promoverlo. Código inválido, vencido, agotado o contexto reutilizado no emite grant y se normaliza por error canónico de recuperación sin revelar existencia ni estado de cuenta. No enviar payload nueva contraseña antes de verificar. Referencias por código a lf_ops.otp_operaciones, otp_politicas, rutas, errores_catalogo y politicas_seguridad; no fijar IDs numéricos ni seleccionar proveedor. Alcance condicionado a recuperación en B2B_AUTENTICACION; fuente CANDIDATO, no autoriza producción ni modifica IG.","efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/448","solicitante":"Cristhian / Claude S22-BA"},