"ba_recovery_client_promotion":false,"ba_recovery_invalid_grant_issued":false,"ba_recovery_error_not_canonical":false,"ba_recovery_account_exposed":false,"ba_recovery_password_payload_before_verify":false,"ba_recovery_policy_route_operation_mismatch":true},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"ba_recovery_verification_gate":false,"ba_recovery_otp_not_server_verified":true,"ba_recovery_context_wrong":false,"ba_recovery_grant_not_opaque_single_use":false,"ba_recovery_grant_not_password_only":false,"ba_recovery_grant_not_temporary":false,"ba_recovery_operational_access":false,"ba_recovery_mfa_satisfied":false,"ba_recovery_client_promotion":false,"ba_recovery_invalid_grant_issued":false,"ba_recovery_error_not_canonical":false,"ba_recovery_account_exposed":false,"ba_recovery_password_payload_before_verify":false,"ba_recovery_policy_route_operation_mismatch":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"}]}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; hashes jsonb:='{}'; hash_all text; t record;
BEGIN
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22BA_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 h:=lf_ops.nucleo_hash_paquete_v1(cd,1); hashes:=hashes||jsonb_build_object(cd,h);
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22BA_VECTOR_FAIL %',cd; END IF;
 END LOOP;
 END LOOP;
 SELECT string_agg(j.key||'='||j.value,',' ORDER BY j.key) INTO hash_all FROM jsonb_each_text(hashes) j;
 RAISE EXCEPTION 'S22BA_HASH_ALL %',hash_all;
END $ba$;
COMMIT;
